@bp.route('/low-stock', methods=['GET'])
def get_low_stock_products():
    """Obtiene productos con stock bajo"""
    threshold = request.args.get('threshold', default=10, type=int)

    if threshold < 0:
        return error_response('El threshold debe ser un entero no negativo', 400)

    try:
        products = Product.query.filter(Product.stock <= threshold).order_by(Product.stock.asc()).all()

        result = [
            {
                'id': product.id,
                'name': product.name,
                'sku': product.sku,
                'stock': product.stock,
                'restock_value': (threshold - product.stock) * (product.cost if product.cost is not None else 0.0)
            }
            for product in products
        ]

        return success_response(
            data=result,
            count=len(result)
        )
    except Exception as e:
        return error_response(f'Error al obtener productos con stock bajo: {str(e)}', 500)

